Read the filter list from F2:F7 and keep only A:C rows whose A value appears in that list. Clear A2:C7, then write the kept rows back starting at row 2 while leaving column F untouched.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

max_row = 7

filter_values = set()
for r in range(2, max_row + 1):
    v = vws.cell(row=r, column=6).value
    if v is not None:
        s = str(v).strip()
        if s:
            filter_values.add(s)

kept_rows = []
for r in range(2, max_row + 1):
    a = vws.cell(row=r, column=1).value
    if a is not None and str(a).strip() in filter_values:
        row_vals = []
        for c in range(1, 4):
            val = vws.cell(row=r, column=c).value
            if isinstance(val, str):
                val = val.strip()
            row_vals.append(val)
        kept_rows.append(row_vals)

for c in range(1, 4):
    h = vws.cell(row=1, column=c).value
    if isinstance(h, str):
        h = h.strip()
    ws.cell(row=1, column=c).value = h

for r in range(2, max_row + 1):
    for c in range(1, 4):
        ws.cell(row=r, column=c).value = None

for i, row_vals in enumerate(kept_rows):
    r = 2 + i
    if r > max_row:
        break
    for c, val in enumerate(row_vals, start=1):
        ws.cell(row=r, column=c).value = val

wb.save(OUT)

print("kept_rows:", len(kept_rows))
print("first_kept:", kept_rows[0] if kept_rows else None)
